'use strict';
let editingProfile=false,saveRevision=0,statusTimer,scrollSaveTimer,polishAnimation,lastPolishRoute='';
const renderBeforePolish=render,navBeforePolish=nav,profileBeforePolish=profile,persistBeforePolish=persist,photosBeforePolish=addPhotos;
const workspaceStatus=document.createElement('div');workspaceStatus.id='workspaceStatus';workspaceStatus.className='workspace-state';workspaceStatus.setAttribute('role','status');workspaceStatus.innerHTML='<span class="workspace-dot" aria-hidden="true"></span><span id="workspaceText"></span>';document.body.appendChild(workspaceStatus);
function showWorkspaceStatus(text,busy=false,error=false){clearTimeout(statusTimer);workspaceStatus.className='workspace-state visible'+(busy?' busy':'')+(error?' error':'');document.querySelector('#workspaceText').textContent=text;if(!busy)statusTimer=setTimeout(()=>workspaceStatus.classList.remove('visible'),error?5000:2200)}
persist=function(){const ok=persistBeforePolish();if(ok){saveRevision++;showWorkspaceStatus('Changes saved in this browser.')}else showWorkspaceStatus('Changes could not be saved. Please retry.',false,true);return ok};
addPhotos=async function(files,target,max){const before=target.length;showWorkspaceStatus('Preparing your photo…',true);try{await photosBeforePolish(files,target,max);showWorkspaceStatus(target.length>before?'Photo ready.':'No photo was added.',false,target.length===before)}catch{showWorkspaceStatus('Photo could not be prepared. Please retry.',false,true)}};
function profileSummary(){const p=state.profile,m=activityMetrics();app.innerHTML=`<section class="card profile-summary"><div class="profile-summary-head"><div class="qa-profile-title">${p.photo?`<img class="qa-avatar" src="${esc(p.photo)}" alt="Your profile photo">`:`<div class="qa-avatar">${esc(qProfileName().slice(0,2).toUpperCase())}</div>`}<div><h1>${esc(qProfileName())}</h1><p class="profile-rank">${esc(p.rank||'Rank not added')}</p><span class="qa-preview-tag">${esc(p.department||'Department not added')} · SELF-REPORTED</span></div></div><button class="profile-edit-small" id="editProfile">Edit</button></div><div class="profile-facts">${p.experience!==''&&p.experience!==undefined?`<span><strong>${esc(p.experience)}</strong> years at sea</span>`:''}${p.country?`<span>${esc(p.country)}</span>`:''}</div><h2 style="font-size:15px;margin:22px 0 8px">About me</h2><p class="profile-bio">${esc(p.bio||'No bio added yet.')}</p><div class="profile-email"><strong>Email · private local profile field</strong>${esc(p.email||'Not added')}<p class="hint">Not shown on question cards. Live account verification is not connected.</p></div></section><div class="profile-summary-grid"><section class="card"><h2>Your contribution journey</h2><p class="qa-status"><strong>${m.asked}</strong> questions · <strong>${m.answered}</strong> questions answered · <strong>${m.outcomes}</strong> outcomes recorded</p><button class="btn quiet" data-nav="progress">View your progress →</button><p class="hint">Saved discussions stay in their original Library topics.</p></section><div>${profileLinks()}</div></div>`;document.querySelector('#editProfile').onclick=()=>{editingProfile=true;render();window.scrollTo(0,0)}}
profile=function(setup=false){if(setup){profileBeforePolish(true);return}if(!editingProfile){profileSummary();return}profileBeforePolish(false);app.insertAdjacentHTML('afterbegin','<div class="profile-edit-head"><h1>Edit profile</h1><button class="profile-edit-small" id="cancelProfileEdit">Cancel</button></div>');document.querySelector('#cancelProfileEdit').onclick=()=>{editingProfile=false;pendingProfileDraft=null;render()};const form=document.querySelector('#qaProfileForm');const save=form.onsubmit;form.onsubmit=e=>{const revision=saveRevision;save(e);if(saveRevision>revision){editingProfile=false;render();window.scrollTo(0,0)}}};
const resumablePages=['settings','help','about','access','review','home','learn','progress','profile','detail','leaderboard','badges','explore','ask'];
function saveLastView(){if(!state.hubOnboardingCompleted||!resumablePages.includes(page))return false;const previous=state.lastView;state.lastView={page,selected:page==='detail'?selected:null,shelfTopic,shelfFileQuery,shelfTopicQuery,shelfStatus,shelfReturn,qaView,qaDepartment,query,topic,sort,scrollY:window.scrollY||0};try{localStorage.setItem('crewanswers-v1',JSON.stringify(state));return true}catch{state.lastView=previous;return false}}
function restoreLastView(){if(!state.hubOnboardingCompleted)return false;const v=state.lastView;if(!v||!resumablePages.includes(v.page))return false;if(v.page==='detail'&&!all().some(q=>q.id===v.selected))return false;page=v.page;selected=v.selected||null;shelfTopic=equipment.includes(v.shelfTopic)?v.shelfTopic:null;shelfFileQuery=v.shelfFileQuery||'';shelfTopicQuery=v.shelfTopicQuery||'';shelfStatus=['all','answered','resolved','saved'].includes(v.shelfStatus)?v.shelfStatus:'all';shelfReturn=!!v.shelfReturn;qaView=v.qaView||'all';qaDepartment=v.qaDepartment||'All departments';query=v.query||'';topic=equipment.includes(v.topic)?v.topic:'All topics';sort=['recent','unanswered','resolved'].includes(v.sort)?v.sort:'recent';editingProfile=false;return true}
nav=function(p){if(state.hubOnboardingCompleted&&(p==='welcome'||p==='gettingstarted'||p==='setup'))p='home';if(p==='profile')editingProfile=false;navBeforePolish(p);if(state.hubOnboardingCompleted&&saveLastView())showWorkspaceStatus('Your place is saved in this browser.')};
function polishRouteKey(){return page+':'+(page==='detail'?selected:page==='learn'?shelfTopic||'topics':page==='profile'?editingProfile?'edit':'summary':page==='home'?state.contributionMode:'')}
function animatePolishedRoute(){const key=polishRouteKey();if(key===lastPolishRoute)return;const old=lastPolishRoute;lastPolishRoute=key;if(!old||typeof app.animate!=='function'||window.matchMedia('(prefers-reduced-motion: reduce)').matches)return;const goingBack=page==='home'||page==='learn'&&!shelfTopic||page==='profile'&&!editingProfile;polishAnimation?.cancel();polishAnimation=app.animate([{opacity:.4,transform:`translateX(${goingBack?-16:16}px)`},{opacity:1,transform:'translateX(0)'}],{duration:210,easing:'cubic-bezier(.2,.7,.2,1)'})}
render=function(){if(state.hubOnboardingCompleted&&(page==='welcome'||page==='gettingstarted'||page==='setup'))page='home';if(['settings','help','about','access','review'].includes(page)){renderNav();app.innerHTML='<p class="hint">Opening your reviewer…</p>';saveLastView();return}renderBeforePolish();document.querySelector('button.profile-action[data-nav="welcome"]')?.remove();document.querySelector('#qaProfileForm button[type="submit"]')?.setAttribute('aria-label','Save your profile changes');for(const nav of document.querySelectorAll('#desktopNav button,#mobileNav button')){if(nav.classList.contains('active'))nav.setAttribute('aria-current','page');else nav.removeAttribute('aria-current')}const instruction=document.querySelector('.shelf-instruction');if(instruction)instruction.innerHTML=instruction.innerHTML.replace('Choose a topic first.','<strong>Choose a topic first.</strong>');animatePolishedRoute();saveLastView()};
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||typeof b.animate!=='function'||window.matchMedia('(prefers-reduced-motion: reduce)').matches)return;b.animate([{transform:'scale(1)'},{transform:'scale(.975)'},{transform:'scale(1)'}],{duration:140,easing:'ease-out'})},true);
window.addEventListener('scroll',()=>{clearTimeout(scrollSaveTimer);scrollSaveTimer=setTimeout(saveLastView,180)},{passive:true});window.addEventListener('pagehide',saveLastView);
const resume=state.hubOnboardingCompleted?state.lastView:null;const restored=restoreLastView();if(state.hubOnboardingCompleted&&!restored)page='home';const boot=document.querySelector('#appBoot');if(boot){boot.style.removeProperty('background');document.querySelector('#bootText').textContent=restored?'Restoring where you left off…':'Opening your saved workspace…'}render();requestAnimationFrame(()=>{if(restored&&resume?.scrollY)window.scrollTo(0,Math.max(0,resume.scrollY));requestAnimationFrame(()=>{if(boot){setTimeout(()=>{boot.classList.add('finished');setTimeout(()=>boot.remove(),190)},Math.max(0,550-(Date.now()-(window.hubOpenedAt||Date.now()))))}if(restored)showWorkspaceStatus('Your last view has been restored.')})});
